    const val AUTH = "auth"
    const val OTP = "otp/{phone}"
    const val MAIN = "main"
    const val KID_DETAIL = "kid/{kidId}"
    const val DIET = "diet/{kidId}"
    const val BOOKING = "booking"
    const val NOTIFICATIONS = "notifications"
    const val ADD_KID = "addKid"
}

